import jmespath

def search_key_recursive(dct0, var0):
    """
    Search recursively for the key 'var0' in a nested dictionary 'dct0'.

    Args:
        dct0 (dict): The nested dictionary to search
        var0 (str): The key to search for

    Returns:
        list: A list of all values associated with the key 'var0' found in the dictionary
    """
    # JMESPath expression to recursively search for the key
    # This uses the recursive descent operator ".." to search at all levels
    expression = f"..{var0}"

    # Execute the search
    result = jmespath.search(expression, dct0)

    # The result might be a single value or a list of values
    # Convert to list if it's not already one for consistent return type
    if result is None:
        return []
    elif not isinstance(result, list):
        return [result]
    else:
